import { useHttp } from "./http";
import { QueryKey, useMutation, useQuery } from "@tanstack/react-query";
import { Task } from "../types/task";
import { Project } from "../types/project";
import {
  useAddConfig,
  useDeleteConfig,
  useEditConfig,
  useReorderTaskConfig,
} from "./use-optimistic-options";
import { SortProps } from "./knaban";
import { sortTasks } from "./order-storage";

export const useTasks = (param?: Partial<Task>) => {
  const client = useHttp();

  return useQuery<Task[]>({
    queryKey: ["tasks", param],
    queryFn: () => client("tasks", { data: param }),
    select: (list) => sortTasks(list),
  });
};

export const useAddTask = (queryKey: QueryKey) => {
  const client = useHttp();

  return useMutation({
    mutationFn: (params: Partial<Task>) =>
      client(`tasks`, {
        data: params,
        method: "POST",
      }),
    ...useAddConfig(queryKey),
  });
};

export const useTask = (id?: number) => {
  const client = useHttp();
  return useQuery<Project>({
    queryKey: ["task", { id }],
    queryFn: () => client(`tasks/${id}`),
    enabled: Boolean(id),
  });
};

export const useEditTask = (queryKey: QueryKey) => {
  const client = useHttp();
  return useMutation({
    mutationFn: (params: Partial<Task>) =>
      client(`tasks/${params.id}`, {
        method: "PATCH",
        data: params,
      }),
    ...useEditConfig(queryKey),
  });
};

export const useDeleteTask = (queryKey: QueryKey) => {
  const client = useHttp();

  return useMutation({
    mutationFn: ({ id }: { id: number }) =>
      client(`tasks/${id}`, {
        method: "DELETE",
      }),
    ...useDeleteConfig(queryKey),
  });
};

export const useReorderTask = (queryKey: QueryKey) => {
  const client = useHttp();
  return useMutation({
    mutationFn: (params: SortProps) => {
      return client("tasks/reorder", {
        data: params,
        method: "POST",
      });
    },
    ...useReorderTaskConfig(queryKey),
  });
};
