import styled from "@emotion/styled";
import { useAuth } from "./context/auth-context";
import { ProjectListScreen } from "./screens/project-list/index";
import { ButtonNoPadding, Row } from "./components/lib";
import { ReactComponent as SoftwareLogo } from "../src/assets/software-logo.svg";
import { Button, Dropdown } from "antd";
import { Navigate, Route, Router, Routes } from "react-router";
import { ProjectScreen } from "./screens/project";
import { BrowserRouter } from "react-router-dom";
import { restRoute } from "./utils";
import React, { useState } from "react";
import { ProjectModel } from "./screens/project-list/project-model";
import { ProjectPopover } from "./components/project-popover";
import { UserPopover } from "components/user-popover";

//登录状态app
export default () => {
  // const [projectModelOpen, setProjectModelOpen] = useState(false);
  return (
    <Container>
      <PageHeader />
      <Main>
        <Routes>
          <Route
            path={"/projects"}
            element={
              <ProjectListScreen
                projectButton={
                  <ButtonNoPadding
                    // onClick={() => setProjectModelOpen(true)}
                    type={"link"}
                  >
                    创建项目
                  </ButtonNoPadding>
                }
              />
            }
          ></Route>
          <Route
            path={"/projects/:projectId/*"}
            element={<ProjectScreen />}
          ></Route>
          {/* 打开自动跳转projects */}
          <Route path="/" element={<Navigate to="/projects" />}></Route>
        </Routes>
      </Main>
      <ProjectModel />
    </Container>
  );
};
const PageHeader = () => {
  return (
    <Header between={true}>
      <HeaderLeft gap={true}>
        <ButtonNoPadding type="link" onClick={restRoute}>
          <SoftwareLogo
            type="link"
            onClick={restRoute}
            color={"rgb(38,132,255)"}
            width={"18rem"}
          ></SoftwareLogo>
        </ButtonNoPadding>
        <ProjectPopover />
        <UserPopover />
        {/* <h2>项目</h2> */}
        {/* <span>用户</span> */}
      </HeaderLeft>
      <HeaderRight>
        <User />
      </HeaderRight>
    </Header>
  );
};

const User = () => {
  const { logout, user } = useAuth();
  return (
    <Dropdown
      // 菜单写在menu属性，不是子节点
      menu={{
        items: [
          {
            key: "logout",
            label: "登出",
            onClick: logout,
          },
        ],
      }}
    >
      {/* 唯一直接子节点：触发器 */}
      <Button type={"link"} onClick={(e) => e.preventDefault()}>
        4=566 Hi,{user?.name}
      </Button>
    </Dropdown>
  );
};

const Container = styled.div`
  display: grid;
  grid-template-rows: 6rem 1fr;
  /* grid-template-columns: 1fr; */
  /* grid-template-areas:
    "header"
    "main"; */
  height: 100vh;
`;

const Header = styled(Row)`
  padding: 3.2rem;
  box-shadow: 0 0 5px 0 rgba(0, 0, 0, 0.1);
  z-index: 1;
`;
const HeaderLeft = styled(Row)``;
const HeaderRight = styled.div``;

const Main = styled.main`
  /* height: calc(100vh-6rem); */
  display: flex;
  /* overflow: hidden;
   */
  min-height: 0;
  flex: 1;
`;
