import { Project } from "../types/types";
import { useAsync } from "./use-async";
import { useCallback, useEffect } from "react";
import { cleanObject } from "../utils";
import { useHttp } from "../utils/http";
import {
  QueryClient,
  QueryKey,
  useMutation,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query"; //扮演use-async
import { useProjectSearchParams } from "../screens/project-list/util";
import {
  useAddConfig,
  useDeleteConfig,
  useEditConfig,
} from "./use-optimistic-options";

export const useProjects = (param?: Partial<Project>) => {
  const client = useHttp();
  return useQuery<Project[]>({
    queryKey: ["projects", param],
    queryFn: () => client("projects", { data: cleanObject(param || {}) }),
  });
};

export const useEditProject = (queryKey: QueryKey) => {
  const client = useHttp();
  return useMutation({
    mutationFn: (params: Partial<Project>) =>
      client(`projects/${params.id}`, {
        method: "PATCH",
        data: params,
      }),
    ...useEditConfig(queryKey),
  });
};

export const useAddProject = (queryKey: QueryKey) => {
  const client = useHttp();
  const QueryClient = useQueryClient();
  return useMutation({
    mutationFn: (params: Partial<Project>) =>
      client(`projects`, {
        method: "POST",
        data: { ...params, created: Date.now() },
      }),
    ...useAddConfig(queryKey),
  });
};

export const useDeleteProject = (queryKey: QueryKey) => {
  const client = useHttp();
  const QueryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id }: { id: number }) =>
      client(`projects/${id}`, {
        method: "DELETE",
      }),
    ...useDeleteConfig(queryKey),
  });
};

//获取project详情的api
export const useProject = (id?: number) => {
  const client = useHttp();
  return useQuery<Project>({
    queryKey: ["projects", { id }], //id改变重新获取
    queryFn: () => client(`projects/${id}`),
    enabled: !!id, //配置属性，当id有值的时候才触发
  });
};
