import { useLocation } from "react-router";
import { useProject } from "../../utils/project";
import { useUrlQueryParam } from "../../utils/url";
import { useCallback, useMemo } from "react";
import { useTask } from "../../utils/task";
import { useDebounce } from "../../utils";

//获取项目的url
export const useProjectIdInUrl = () => {
  const { pathname } = useLocation();
  const id = pathname.match(/projects\/(\d+)/)?.[1];
  return Number(id);
};
//返回整个project
export const useProjectInUrl = () => useProject(useProjectIdInUrl());
export const useKanbanSearchParams = () => ({ projectId: useProjectIdInUrl() });
export const useKanbansQueryKey = () => ["kanbans", useKanbanSearchParams()];
export const useTasksSearchParams = () => {
  const [param, setUrlParam] = useUrlQueryParam([
    "name",
    "typeId",
    "processorId",
    "tagId",
  ]);
  const projectId = useProjectIdInUrl();
  const debounceName = useDebounce(param.name, 200);
  const setSearchParams = (newParam: {
    name?: string;
    typeId?: number;
    processorId?: number;
    tagId?: number;
  }) => {
    setUrlParam({
      ...newParam,
      typeId:
        newParam.typeId === undefined ? undefined : String(newParam.typeId),
      processorId:
        newParam.processorId === undefined
          ? undefined
          : String(newParam.processorId),
      tagId: newParam.tagId === undefined ? undefined : String(newParam.tagId),
    });
  };
  return [
    useMemo(
      () => ({
        projectId,
        typeId: Number(param.typeId) || undefined,
        processorId: Number(param.processorId) || undefined,
        tagId: Number(param.tagId) || undefined,
        name_like: debounceName,
      }),
      [projectId, param, debounceName],
    ),
    setSearchParams,
  ] as const;
};

export const useTasksQueryKey = () => {
  const [params] = useTasksSearchParams();
  return ["tasks", params];
};

export const useTaskModal = () => {
  const [{ editingTaskId }, setEditingTaskId] = useUrlQueryParam([
    "editingTaskId",
  ]);
  const { data: editingTask, isLoading } = useTask(Number(editingTaskId));
  const startEdit = useCallback(
    (id: number) => {
      setEditingTaskId({ editingTaskId: String(id) });
    },
    [setEditingTaskId],
  );
  const close = useCallback(() => {
    setEditingTaskId({ editingTaskId: "" });
  }, [setEditingTaskId]);

  return {
    editingTaskId,
    editingTask,
    isLoading,
    startEdit,
    close,
  };
};
