import {
  Button,
  DatePicker,
  Drawer,
  DrawerProps,
  Form,
  Input,
  Spin,
} from "antd";
import { useAddEpic } from "../../utils/epic";
import { useEpicsQueryKey } from "./util";
import { useProjectIdInUrl } from "../kanban/utils";
import styled from "@emotion/styled";

export const CreateEpic = (
  props: Pick<DrawerProps, "open"> & { onClose: () => void },
) => {
  const { mutate: addEpic, isPending, error } = useAddEpic(useEpicsQueryKey());
  const [form] = Form.useForm();
  const projectId = useProjectIdInUrl();
  const onFinish = async (values: any) => {
    await addEpic({
      ...values,
      projectId,
      start: values.start?.format("YYYY-MM-DD"),
      end: values.end?.format("YYYY-MM-DD"),
    });
    props.onClose();
  };
  return (
    <Drawer
      forceRender={true}
      destroyOnClose={true}
      width={"100%"}
      open={props.open}
      onClose={props.onClose}
    >
      <Container>
        {isPending ? (
          <Spin size="large" />
        ) : (
          <>
            {error && <h2>{error.message}</h2>}
            <h1>创建任务组</h1>
            <Form
              form={form}
              layout="vertical"
              style={{ width: "40rem" }}
              onFinish={onFinish}
            >
              <Form.Item
                label={"名称"}
                name={"name"}
                rules={[{ required: true, message: "请输入任务组名" }]}
              >
                <Input placeholder="请输入任务组名称" />
              </Form.Item>

              <Form.Item
                label={"开始时间"}
                name={"start"}
                rules={[{ required: true, message: "请选择开始时间" }]}
              >
                <DatePicker style={{ width: "100%" }} />
              </Form.Item>

              <Form.Item
                label={"结束时间"}
                name={"end"}
                rules={[{ required: true, message: "请选择结束时间" }]}
              >
                <DatePicker style={{ width: "100%" }} />
              </Form.Item>

              <Form.Item style={{ textAlign: "right" }}>
                <Button loading={isPending} type="primary" htmlType="submit">
                  提交
                </Button>
              </Form.Item>
            </Form>
          </>
        )}
      </Container>
    </Drawer>
  );
};

const Container = styled.div`
  flex-direction: column;
  height: 80vh;
  display: flex;
  justify-content: center;
  align-items: center;
`;
