import { Button, Divider, Popover, Typography } from "antd";
import { List } from "antd";
import React from "react";
import { useProjects } from "../utils/project";
import styled from "@emotion/styled";
import { ButtonNoPadding } from "./lib";
import { useProjectModel } from "../screens/project-list/util";

export const ProjectPopover = () => {
  const { open } = useProjectModel();
  const { data: projects, refetch } = useProjects(); //获取项目列表
  const pinnedProjects = projects?.filter((project) => project.pin); //获取所有收藏项目
  const content = (
    <ContentContainer>
      <Typography.Text type="secondary">收藏项目</Typography.Text>
      <List>
        {pinnedProjects?.map((project) => (
          <List.Item.Meta title={project.name} />
        ))}
      </List>

      {/* antd自带的分割线 */}
      <Divider />

      <ButtonNoPadding onClick={open} type={"link"}>
        创建项目
      </ButtonNoPadding>
    </ContentContainer>
  );
  return (
    <Popover
      placement="bottom"
      content={content}
      onOpenChange={() => refetch()}
    >
      {/* 当鼠标悬浮的时候，从下面显示一个列表 */}
      <span> 项目</span>
    </Popover>
  );
};

const ContentContainer = styled.div`
  min-width: 30rem;
`;
