import React, { useCallback } from "react";
import { useDocumentTitle } from "../../utils";
import {
  useKanbanSearchParams,
  useKanbansQueryKey,
  useProjectInUrl,
  useTasksQueryKey,
  useTasksSearchParams,
} from "./utils";
import { KanbanColumn } from "./kanban-column";
import styled from "@emotion/styled";
import { useKanbans, useReorderKanban } from "../../utils/knaban";
import { SearchPanel } from "./search-panel";
import { ScreenContainer } from "../../components/lib";
import { useReorderTask, useTasks } from "../../utils/task";
import { Spin } from "antd";
import { CreateKanban } from "../kanban/ctreate-kanban";
import { TaskModal } from "./task-modal";
import { DragDropContext, DropResult } from "react-beautiful-dnd";
import { Drag, Drop, DropChild } from "../../components/drag-and-drop";
import { Task } from "../../types/task";
import { Kanban } from "../../types/kanban";
import { useQueryClient } from "@tanstack/react-query";
import { saveKanbanOrder, saveTaskOrder } from "../../utils/order-storage";
import { Profiler } from "components/profilter";

export const KanbanScreen = () => {
  useDocumentTitle("看板列表");

  const { data: currentProject } = useProjectInUrl();
  const { data: kanbans, isLoading: kanbanIsLoading } = useKanbans(
    useKanbanSearchParams(),
  );
  const [searchParams] = useTasksSearchParams();
  const { isLoading: taskIsLoading } = useTasks(searchParams);
  const isLoading = taskIsLoading || kanbanIsLoading;

  const onDragEnd = useDragEnd();
  return (
    <Profiler id={"看板页面"}>
      <DragDropContext onDragEnd={onDragEnd}>
        <ScreenContainer>
          <h1>{currentProject?.name}看板</h1>
          <SearchPanel />
          {isLoading ? (
            <Spin size={"large"} />
          ) : (
            <ColumnsContainer>
              <Drop
                type={"COLUMN"}
                direction={"horizontal"}
                droppableId={"kanban"}
              >
                <DropChild style={{ display: "flex" }}>
                  {kanbans?.map((kanban: Kanban, index) => (
                    <Drag
                      key={kanban.id}
                      draggableId={"kanban" + kanban.id}
                      index={index}
                    >
                      <KanbanColumn kanban={kanban} key={kanban.id} />
                    </Drag>
                  ))}
                </DropChild>
              </Drop>
              <CreateKanban />
            </ColumnsContainer>
          )}
          <TaskModal />
        </ScreenContainer>
      </DragDropContext>
    </Profiler>
  );
};

export const useDragEnd = () => {
  const queryClient = useQueryClient();
  const { data: kanbans } = useKanbans(useKanbanSearchParams());
  const { data: currentProject } = useProjectInUrl();
  const { mutate: reorderKanban } = useReorderKanban(useKanbansQueryKey());
  const { mutate: reorderTask } = useReorderTask(useTasksQueryKey());
  const kanbanQueryKey = useKanbansQueryKey();
  const taskQueryKey = useTasksQueryKey();
  const [searchParams] = useTasksSearchParams();
  const { data: allTasks = [] } = useTasks(searchParams);
  return useCallback(
    ({ source, destination, type }: DropResult) => {
      if (!destination) {
        return;
      }
      // 看板排序
      if (type === "COLUMN") {
        const fromId = kanbans?.[source.index].id;
        const toId = kanbans?.[destination.index].id;
        if (!fromId || !toId || fromId === toId) {
          return;
        }
        const reorderType =
          destination.index > source.index ? "after" : "before";
        reorderKanban({ fromId, referenceId: toId, type: reorderType });
        // 乐观更新用 setTimeout 等 setQueryData 执行完再存
        setTimeout(() => {
          const updated = queryClient.getQueryData<Kanban[]>(kanbanQueryKey);
          if (updated && currentProject?.id != null) {
            saveKanbanOrder(
              currentProject.id,
              updated.map((k) => k.id),
            );
          }
        }, 0);
      }
      if (type === "ROW") {
        const fromKanbanId = +source.droppableId;
        const toKanbanId = +destination.droppableId;
        const fromTask = allTasks.filter(
          (task: Task) => task.kanbanId === fromKanbanId,
        )[source.index];
        const toTask = allTasks.filter(
          (task: Task) => task.kanbanId === toKanbanId,
        )[destination.index];
        if (fromTask?.id === toTask?.id) {
          return;
        }
        const reorderType =
          fromKanbanId === toKanbanId && destination.index > source.index
            ? "after"
            : "before";
        reorderTask({
          fromId: fromTask?.id,
          referenceId: toTask?.id,
          fromKanbanId,
          toKanbanId,
          type: reorderType,
        });
        setTimeout(() => {
          const updated = queryClient.getQueryData<Task[]>(taskQueryKey);
          if (!updated) return;
          const byKanban: Record<number, Task[]> = {};
          for (const t of updated) {
            (byKanban[t.kanbanId] ||= []).push(t);
          }
          for (const kId of Object.keys(byKanban)) {
            saveTaskOrder(
              Number(kId),
              byKanban[Number(kId)].map((t) => t.id),
            );
          }
        }, 0);
      }
    },
    [
      kanbans,
      reorderKanban,
      allTasks,
      reorderTask,
      currentProject?.id,
      queryClient,
      kanbanQueryKey,
      taskQueryKey,
    ],
  );
};

export const ColumnsContainer = styled("div")`
  display: flex;
  overflow-x: scroll;
  flex: 1;
`;
