import { useMemo } from "react";
import { useUrlQueryParam } from "../../utils/url";
import { useProject } from "../../utils/project";
import { useSearchParams } from "react-router-dom";

//项目列表搜索的参数
export const useProjectSearchParams = () => {
  const [param, setUrlParam] = useUrlQueryParam(["name", "personId"]);
  const setParam = (newParam: { name?: string; personId?: number }) => {
    setUrlParam({
      ...newParam,
      personId:
        newParam.personId === undefined ? undefined : String(newParam.personId),
    });
  };
  return [
    useMemo(
      () => ({
        ...param,
        personId: Number(param.personId) || undefined,
      }),
      [param],
    ),
    setParam,
  ] as const;
};

export const useProjectsQueryKey = () => {
  const [params] = useProjectSearchParams();
  return ["projects", params];
};

export const useProjectModel = () => {
  const [{ projectCreate, editingProjectId }, setQuery] = useUrlQueryParam([
    "projectCreate", //判断是不是创建
    "editingProjectId",
  ]);

  const { data: editingProject, isLoading } = useProject(
    Number(editingProjectId),
  );

  const open = () => setQuery({ projectCreate: "true" });

  const close = () =>
    setQuery({
      projectCreate: "",
      editingProjectId: "",
    });

  const startEdit = (id: number) => setQuery({ editingProjectId: String(id) });

  //retrurn返回第一个参数是标志projectmodel是不是打开
  return {
    projectModelOpen: projectCreate === "true" || Boolean(editingProjectId), //任意一个有值的时候都要打开表单
    open,
    close,
    startEdit,
    editingProject,
    isLoading,
  };
};
