import { Row, ScreenContainer } from "../../components/lib";
import { useProjectInUrl } from "../kanban/utils";
import { useEpics } from "../../utils/epic";
import { useEpicSearchParams, useEpicsQueryKey } from "./util";
import { useTasks } from "../../utils/task";
import { useDeleteEpic } from "../../utils/epic";
import { Link } from "react-router-dom";
import { Button, Modal } from "antd";
import { useDocumentTitle } from "../../utils";
import { useState } from "react";
import { CreateEpic } from "./create-apic";

export const EpicScreen = () => {
  useDocumentTitle("任务组列表");
  const { data: currentProject } = useProjectInUrl();
  const { data: epics } = useEpics(useEpicSearchParams());
  const { data: tasks } = useTasks({ projectId: currentProject?.id });
  const { mutate: deleteEpic } = useDeleteEpic(useEpicsQueryKey());
  const [epicCreateOpen, setEpicCreateOpen] = useState(false);

  const confirmDelete = (id: number) => {
    Modal.confirm({
      title: "确定删除这个任务组吗",
      content: "点击确定删除",
      okText: "确定",
      onOk() {
        deleteEpic({ id });
      },
    });
  };

  return (
    <ScreenContainer>
      <Row between={true}>
        <h1>{currentProject?.name}任务组</h1>
        <Button onClick={() => setEpicCreateOpen(true)} type="link">
          创建任务组
        </Button>
      </Row>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "1.5rem",
          overflow: "scroll",
        }}
      >
        {epics?.map((epic: any) => (
          <div key={epic.id}>
            <Row between={true}>
              <span style={{ fontWeight: 500, fontSize: "1rem" }}>
                {epic.name}
              </span>
              <a
                onClick={() => confirmDelete(epic.id)}
                style={{ color: "#1890ff", cursor: "pointer" }}
              >
                删除
              </a>
            </Row>
            <div
              style={{
                color: "#999",
                fontSize: "0.875rem",
                marginTop: "0.25rem",
              }}
            >
              开始时间：{epic.start || "-"} &nbsp; 结束时间：{epic.end || "-"}
            </div>
            <div style={{ marginTop: "0.25rem", fontSize: "0.875rem" }}>
              {tasks
                ?.filter((task) => task.epicId === epic.id)
                .map((task, idx, arr) => (
                  <span key={task.id}>
                    <Link
                      to={`/projects/${currentProject?.id}/kanban?editingTaskId=${task.id}`}
                      style={{ color: "#666", marginRight: "0.25rem" }}
                    >
                      {task.name}
                    </Link>
                    {idx < arr.length - 1 && " "}
                  </span>
                ))}
            </div>
          </div>
        ))}
      </div>
      <CreateEpic
        onClose={() => setEpicCreateOpen(false)}
        open={epicCreateOpen}
      />
    </ScreenContainer>
  );
};
