import { Button, Dropdown, Modal, Table } from "antd";
import { User, Project } from "../../types/types";
import dayjs from "dayjs";
import type { TableProps } from "antd";
import { Link } from "react-router-dom";
import { Pin } from "../../components/pin";
import { useDeleteProject, useEditProject } from "../../utils/project";
import React from "react";
import { useProjectModel, useProjectsQueryKey } from "./util";
import { ButtonNoPadding } from "../../components/lib";

//约束list参数类型
interface ListProps extends TableProps<Project> {
  // list: Project[];
  users: User[]; //一个User类型的数组
  projectButton: React.ReactNode;
}
export const List = React.memo(({ users, ...props }: ListProps) => {
  const { mutate } = useEditProject(useProjectsQueryKey());
  const pinProject = (id: number) => (pin: boolean) => mutate({ id, pin });

  return (
    <Table
      rowKey={"id"}
      pagination={false} //不需要渲染
      columns={[
        {
          //实现收藏功能
          title: <Pin checked={true} disabled={true} />,
          render(value, project) {
            //当用户点击的时候要向服务端发送请求，要先定义向服务端发送编辑请求的方法
            return (
              <Pin
                checked={project.pin}
                onCheckedChange={pinProject(project.id)}
              />
            );
          },
        },
        {
          title: "名称",
          sorter: (a, b) => a.name.localeCompare(b.name),
          render(value, project) {
            return <Link to={`/projects/${project.id}`}>{project.name}</Link>;
          },
        },
        {
          title: "部门",
          dataIndex: "organization",
        },
        {
          title: "负责人",
          render(value, project) {
            return (
              <span>
                {users.find((user) => user.id === project.personId)?.name ||
                  "未知"}
              </span>
            );
          },
        },
        {
          title: "创建时间",
          render(value, project) {
            return (
              <span>
                {project.created
                  ? dayjs(project.created).format("YYYY-MM-DD")
                  : "无"}
              </span>
            );
          },
        },
        {
          render(value, project) {
            return <More project={project}></More>;
          },
        },
      ]} //每一列该怎么渲染
      {...props}
    />
  );
});

const More = ({ project }: { project: Project }) => {
  const editProject = (id: number) => () => startEdit(id);
  const { startEdit } = useProjectModel();
  const { mutate: deleteProject } = useDeleteProject(useProjectsQueryKey());
  const confirmDeleteProject = (id: number) => {
    Modal.confirm({
      title: "确定删除这个项目吗",
      content: "点击确定删除",
      okText: "确定",
      onOk() {
        deleteProject({ id });
      },
    });
  };

  return (
    <Dropdown
      menu={{
        items: [
          {
            key: "edit",
            label: (
              <ButtonNoPadding onClick={editProject(project.id)}>
                编辑
              </ButtonNoPadding>
            ),
          },
          {
            key: "delete",
            label: (
              <ButtonNoPadding onClick={() => confirmDeleteProject(project.id)}>
                删除
              </ButtonNoPadding>
            ),
          },
        ],
      }}
    >
      <Button type="link">...</Button>
    </Dropdown>
  );
};
