import { useHttp } from "./http";
import { QueryKey, useMutation, useQuery } from "@tanstack/react-query";
import { Kanban } from "../types/kanban";
import {
  useAddConfig,
  useDeleteConfig,
  useReorderKanbanConfig,
} from "./use-optimistic-options";
import { sortKanbans } from "./order-storage";

export const useKanbans = (param?: Partial<Kanban>) => {
  const client = useHttp();

  return useQuery<Kanban[]>({
    queryKey: ["kanbans", param],
    queryFn: () => client("kanbans", { data: param }),
    select: (list) => sortKanbans(list, param?.projectId || 0),
  });
};

export const useAddKanban = (queryKey: QueryKey) => {
  const client = useHttp();

  return useMutation({
    mutationFn: (params: Partial<Kanban>) =>
      client(`kanbans`, {
        data: params,
        method: "POST",
      }),
    ...useAddConfig(queryKey),
  });
};

export const useDeleteKanban = (queryKey: QueryKey) => {
  const client = useHttp();

  return useMutation({
    mutationFn: ({ id }: { id: number }) =>
      client(`kanbans/${id}`, {
        method: "DELETE",
      }),
    ...useDeleteConfig(queryKey),
  });
};

export interface SortProps {
  // 要重新排序的 item
  fromId: number;
  // 目标 item
  referenceId: number;
  // 放在目标item的前还是后
  type: "before" | "after";
  fromKanbanId?: number;
  toKanbanId?: number;
}

export const useReorderKanban = (queryKey: QueryKey) => {
  const client = useHttp();
  return useMutation({
    mutationFn: (params: SortProps) => {
      return client("kanbans/reorder", {
        data: params,
        method: "POST",
      });
    },
    ...useReorderKanbanConfig(queryKey),
  });
};
