import { Button, Drawer, Form, Input, Spin } from "antd";
import { useProjectModel, useProjectsQueryKey } from "./util";
import { title } from "process";
import { UserSelect } from "../../components/user-select";
import { useAddProject, useEditProject } from "../../utils/project";
import { useForm } from "antd/es/form/Form";
import { useEffect } from "react";
import styled from "@emotion/styled";

export const ProjectModel = () => {
  const { projectModelOpen, close, editingProject, isLoading } =
    useProjectModel();
  // const useMutateProject = editingProject ? useEditProject : useAddProject;
  const useEditMutation = useEditProject(useProjectsQueryKey());
  const useAddMutation = useAddProject(useProjectsQueryKey());

  const {
    mutateAsync,
    error,
    isPending: mutateLoading,
  } = editingProject ? useEditMutation : useAddMutation;

  const [form] = useForm();

  const onFinish = (values: any) => {
    mutateAsync({ ...editingProject, ...values }).then(() => {
      form.resetFields();
      close();
    });
  };

  const closeModal = () => {
    form.resetFields(); //清空输入框
    close();
  };

  const title = editingProject ? "编辑项目" : "创建项目";
  useEffect(() => {
    form.setFieldsValue(editingProject);
  }, [editingProject, form]);

  return (
    <Drawer width={"100%"} open={projectModelOpen} onClose={closeModal}>
      <Container>
        {isLoading ? (
          <Spin size="large" />
        ) : (
          <>
            {error && <h2>{error.message}</h2>}
            <h1>{title}</h1>
            <Form
              form={form}
              layout="vertical"
              style={{ width: "40rem" }}
              onFinish={onFinish}
            >
              <Form.Item
                label={"名称"}
                name={"name"}
                rules={[{ required: true, message: "请输入项目名" }]}
              >
                <Input placeholder="请输入项目名称" />
              </Form.Item>
              <Form.Item
                label={"部门"}
                name={"organization"}
                rules={[{ required: true, message: "请输入部门名" }]}
              >
                <Input placeholder="请输入项目名称" />
              </Form.Item>
              <Form.Item label={"负责人"} name={"personId"}>
                <UserSelect defaultOptionName="负责人" />
              </Form.Item>
              <Form.Item style={{ textAlign: "right" }}>
                <Button
                  loading={mutateLoading}
                  type="primary"
                  htmlType="submit"
                >
                  {/* 点击提交触发onfinish方法 */}
                  提交
                </Button>
              </Form.Item>
            </Form>
          </>
        )}
      </Container>
    </Drawer>
  );
};

const Container = styled.div`
  flex-direction: column;
  height: 80vh;
  display: flex;
  justify-content: center;
  align-items: center;
`;
