import { useUsers } from "../utils/user";
import { IdSelect } from "./id-select";
import React from "react";

export const UserSelect = (
  props: Omit<React.ComponentProps<typeof IdSelect>, "options">,
) => {
  const { data: users } = useUsers();
  return (
    <IdSelect
      {...props}
      options={(users || []).map((u) => ({
        name: u.name,
        id: Number(u.id),
      }))}
    />
  );
};
