// localStorage 持久化看板和任务的拖拽排序
const KANBAN_ORDER_KEY = (projectId: number) => `kanban_order_${projectId}`;
const TASK_ORDER_KEY = (kanbanId: number) => `task_order_${kanbanId}`;

export const loadKanbanOrder = (projectId: number): number[] => {
  try {
    const raw = localStorage.getItem(KANBAN_ORDER_KEY(projectId));
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
};

export const saveKanbanOrder = (projectId: number, order: number[]) => {
  localStorage.setItem(KANBAN_ORDER_KEY(projectId), JSON.stringify(order));
};

export const sortKanbans = <T extends { id: number }>(
  list: T[] | undefined,
  projectId: number,
): T[] => {
  if (!list?.length) return list || [];
  const order = loadKanbanOrder(projectId);
  if (!order.length) return list;
  const idSet = new Set(order);
  const ordered = order
    .map((id) => list.find((item) => item.id === id))
    .filter((item): item is T => !!item);
  // localStorage 里没有的新 kanban 追加到末尾
  const rest = list.filter((item) => !idSet.has(item.id));
  return [...ordered, ...rest];
};

export const loadTaskOrder = (kanbanId: number): number[] => {
  try {
    const raw = localStorage.getItem(TASK_ORDER_KEY(kanbanId));
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
};

export const saveTaskOrder = (kanbanId: number, order: number[]) => {
  localStorage.setItem(TASK_ORDER_KEY(kanbanId), JSON.stringify(order));
};

export const sortTasks = <T extends { id: number; kanbanId: number }>(
  list: T[] | undefined,
): T[] => {
  if (!list?.length) return list || [];
  // 按 kanbanId 分组后各自排序
  const byKanban: Record<number, T[]> = {};
  for (const item of list) {
    (byKanban[item.kanbanId] ||= []).push(item);
  }
  const result: T[] = [];
  for (const kid of Object.keys(byKanban)) {
    const kId = Number(kid);
    const order = loadTaskOrder(kId);
    const group = byKanban[kId];
    if (!order.length) {
      result.push(...group);
      continue;
    }
    const idSet = new Set(order);
    const ordered = order
      .map((id) => group.find((t) => t.id === id))
      .filter((t): t is T => !!t);
    const rest = group.filter((t) => !idSet.has(t.id));
    result.push(...ordered, ...rest);
  }
  return result;
};
