import { QueryKey, useQueryClient } from "@tanstack/react-query";
import { reorder } from "./reorder";
import { Task } from "../types/task";
import { Kanban } from "../types/kanban";
import { saveKanbanOrder, saveTaskOrder } from "./order-storage";

export const useConfig = (
  queryKey: QueryKey,
  callback: (target: any, old?: any[]) => any[],
  options?: { noInvalidate?: boolean },
) => {
  const queryClient = useQueryClient();
  return {
    onSuccess: options?.noInvalidate
      ? undefined
      : () => queryClient.invalidateQueries({ queryKey }),
    async onMutate(target: any) {
      const previousItems = queryClient.getQueryData(queryKey);
      queryClient.setQueryData(queryKey, (old?: any[]) => {
        return callback(target, old);
      });
      return { previousItems };
    },
    onError(error: any, newItem: any, context: any) {
      queryClient.setQueryData(queryKey, context.previousItems);
    },
  };
};

export const useDeleteConfig = (queryKey: QueryKey) =>
  useConfig(
    queryKey,
    (target, old) => old?.filter((item) => item.id !== target.id) || [],
  );
export const useEditConfig = (queryKey: QueryKey) =>
  useConfig(
    queryKey,
    (target, old) =>
      old?.map((item) =>
        item.id === target.id ? { ...item, ...target } : item,
      ) || [],
  );
export const useAddConfig = (queryKey: QueryKey) =>
  useConfig(queryKey, (target, old) => (old ? [...old, target] : []));

export const useReorderKanbanConfig = (queryKey: QueryKey) =>
  useConfig(
    queryKey,
    (target, old) => {
      const result = reorder({ list: old, ...target });
      // 乐观更新同步存 localStorage
      const list = result as Kanban[];
      const projectId = list[0]?.projectId;
      if (projectId != null) {
        saveKanbanOrder(
          projectId,
          list.map((k) => k.id),
        );
      }
      return result;
    },
    { noInvalidate: true },
  );

export const useReorderTaskConfig = (queryKey: QueryKey) =>
  useConfig(
    queryKey,
    (target, old) => {
      const orderedList = reorder({ list: old, ...target }) as Task[];
      // 乐观更新同步存 localStorage
      const updated = orderedList.map((item) =>
        item.id === target.fromId
          ? { ...item, kanbanId: target.toKanbanId }
          : item,
      );
      // 按 kanbanId 分组存
      const byKanban: Record<number, Task[]> = {};
      for (const t of updated) {
        (byKanban[t.kanbanId] ||= []).push(t);
      }
      for (const kId of Object.keys(byKanban)) {
        saveTaskOrder(
          Number(kId),
          byKanban[Number(kId)].map((t) => t.id),
        );
      }
      return updated;
    },
    { noInvalidate: true },
  );
