import { SearchPanel } from "./search-panel";
import { List } from "./list";
import { useDebounce, useDocumentTitle } from "../../utils/index";
import styled from "@emotion/styled";
import { Button, Typography } from "antd";
// import { useProjects } from "src/utils/project";
import { useProjects } from "../../utils/project";
import { useUsers } from "../../utils/user";
import { useUrlQueryParam } from "../../utils/url";
import { useProjectModel, useProjectSearchParams } from "./util";
import { Row } from "../../components/lib";
import React from "react";
import { Profiler } from "components/profilter";

export const ProjectListScreen = (props: {
  projectButton: React.ReactNode;
}) => {
  useDocumentTitle("项目列表", false);
  const { open } = useProjectModel();

  //基本类型可以放到依赖里；组件状态可以放到依赖里；非组件状态的对象，绝不可以放到依赖里面
  const [param, setParam] = useProjectSearchParams();
  const debounceParam = useDebounce(param, 500);
  const { isLoading, error, data: list } = useProjects(debounceParam);
  const { data: users } = useUsers();

  console.log(useUrlQueryParam(["name"]));

  return (
    <Profiler id={"项目列表"}>
      <Container>
        <Row between={true}>
          <h1>项目列表</h1>
          <Button onClick={open}>创建项目</Button>
        </Row>

        <SearchPanel users={users || []} param={param} setParam={setParam} />
        {error ? (
          <Typography.Text type={"danger"}>{error.message}</Typography.Text>
        ) : undefined}
        <List
          projectButton={props.projectButton}
          loading={isLoading}
          users={users || []}
          dataSource={Array.isArray(list) ? list : []}
        />
      </Container>
    </Profiler>
  );
};

ProjectListScreen.whyDidYouRender = false;

const Container = styled.div`
  padding: 3.2rem;
`;
