import { Button, Form, Modal } from "antd";
import { useTaskModal, useTasksQueryKey } from "./utils";
import { useDeleteTask, useEditTask } from "../../utils/task";
import { useEffect } from "react";
// import Modal from "antd/es/modal/Modal";
import Input from "antd/es/input/Input";
import { UserSelect } from "../../components/user-select";
import { TaskTypeSelect } from "../../components/task-type-select";

const layout = {
  labelCol: { span: 8 }, //文字
  wrapperCol: { span: 16 }, //表单
};

export const TaskModal = () => {
  const [form] = Form.useForm();
  const { editingTaskId, editingTask, close } = useTaskModal();

  const { mutateAsync: editTask, isPending: editLoading } =
    useEditTask(useTasksQueryKey());
  const { mutate: deleteTask } = useDeleteTask(useTasksQueryKey());
  const onCanel = () => {
    close();
    form.resetFields();
  };
  const onOk = async () => {
    await editTask({ ...editingTask, ...form.getFieldsValue() });
    close();
  };

  const startDelete = () => {
    const taskId = editingTask?.id;
    close();
    Modal.confirm({
      okText: "确定",
      cancelText: "取消",
      title: "确定删除任务吗",
      onOk() {
        return deleteTask({ id: Number(taskId) });
      },
    });
  };

  useEffect(() => {
    form.setFieldsValue(editingTask);
  }, [form, editingTask]);
  return (
    <Modal
      onCancel={onCanel}
      onOk={onOk}
      okText={"确认"}
      cancelText={"取消"}
      confirmLoading={editLoading}
      title={"编辑任务"}
      open={!!editingTaskId}
    >
      <Form {...layout} initialValues={editingTask} form={form}>
        <Form.Item
          label={"任务名"}
          name={"name"}
          rules={[{ required: true, message: "请输入任务名" }]}
        >
          <Input />
        </Form.Item>
        <Form.Item label={"经办人名"} name={"processorId"}>
          <UserSelect defaultOptionName="经办人" />
        </Form.Item>{" "}
        <Form.Item label={"类型"} name={"typeId"}>
          <TaskTypeSelect />
        </Form.Item>
      </Form>
      <div style={{ textAlign: "right" }}>
        <Button size="small" style={{ fontSize: "14px" }} onClick={startDelete}>
          删除
        </Button>
      </div>
    </Modal>
  );
};
